    p_str = str(p)
    n = len(p_str)

    # Function to check if a number can be formed by concatenating two numbers
    def can_form(a, b):
        return str(a) + str(b) == p_str

    # Recursive function to find the maximum number of elements
    def dfs(start, end):
        if start > end:
            return 0
        if start == end:
            return 1

        max_count = 1
        for i in range(start, end):
            for j in range(i + 1, end + 1):
                if can_form(int(p_str[start:i+1]), int(p_str[i+1:j+1])):
                    count = dfs(start, i) + dfs(i+1, j-1) + dfs(j+1, end)
                    max_count = max(max_count, count)

        return max_count

    return dfs(0, n - 1)

